INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE code = 'UZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & transmission', '[["Invoice format", "Structured electronic document, reported as JSON"], ["Signature", "ETsP digital signature — bilateral: the seller signs to issue, the buyer signs to accept"], ["Channels", "The state platform, or any of 27 registered private EDO operators"], ["Interoperability", "Handled by the state-designated roaming operator, the state enterprise \"Yangi Texnologiyalar\" (Resolution 522)"], ["Classification codes", "ITSPU codes from the national e-catalogue, which held over 454,500 codes as of September 2024"], ["European standards", "Not EN 16931; Uzbekistan is not a Peppol authority"]]', 'The JSON format is stated consistently across independent secondary sources but no primary technical specification was located in this research round — treat the format name as well-supported rather than confirmed.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE code = 'UZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Retention: two different clocks', '[["Operators", "Must retain confirmed electronic documents for at least 5 years, after which archiving passes to the tax authority"], ["Taxpayers", "General accounting and tax document retention was reduced from 5 years to 3 years from 1 January 2024 by Law No. ZRU-891, tracking the Tax Code Article 88 limitation period"], ["Longer periods", "Fixed-asset and depreciation records are held longer"]]', 'These are genuinely separate obligations and are frequently conflated. Your operator holding an invoice for five years does not extend your own three-year retention duty, and your three-year duty does not shorten theirs.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE code = 'UZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who must issue electronic invoices', '[["All business entities", "Mandatory since 1 January 2020 under Resolution 522 — no revenue threshold on the obligation itself"], ["Self-employed persons", "Brought in from 1 January 2026 by Law No. ZRU-1108, on a par with legal entities and individual entrepreneurs"], ["B2G", "In scope"], ["B2C", "Not an electronic exchange in practice — see the note"], ["Only exemption found", "Transactions involving state secrets, where paper invoices in at least two copies remain permitted"]]', 'B2C scope is genuinely contested. Two international compliance sources list B2C as in scope, but Uzbek practitioner guidance states that for sales to individual consumers the seller prints and hands over the document, with the electronic loop not applying — retail being covered instead by online cash registers and QR-code payment duties. This page does not assert a B2C e-invoicing mandate.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE code = 'UZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔍 Why this page does not call Uzbekistan a clearance regime', NULL, NULL, 'A widely-circulated industry booklet describes Uzbekistan as a real-time clearance model in which the tax authority validates an invoice before it becomes legally final. The evidence points elsewhere, so this page describes it differently and explains why. The documented workflow runs seller to buyer, not seller to tax authority to buyer: the seller signs and transmits, then the buyer either certifies with their own signature or rejects with stated reasons, within a ten-day window after which the reject option disables. A buyer-acceptance clock is the signature of an exchange model. The 2026 risk system reinforces the point — it colours invoices rather than blocking them, and a flagged invoice is still validly issued, with the consequence falling on the buyer''s input VAT timing rather than the invoice''s validity. Under genuine pre-clearance, a failed invoice would not exist at all. There is a technical registration gate, and since 2026 a risk gate affecting VAT credit, but no fiscal approval gate suspending legal validity pending tax-authority sign-off. One further caveat, stated rather than buried: Appendix 2 to Resolution 489, which carries the operative procedure, could not be retrieved in full from a primary source in this research round, so the workflow description above rests on high-quality Uzbek specialist legal press rather than statutory text.');
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 1, 'pills' FROM countries WHERE code = 'UZ';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The exchange flow', 'An Uzbek electronic invoice moves through this sequence:', 'The decisive step is the buyer''s, not the tax authority''s — which is why this page describes Uzbekistan as centralised exchange rather than clearance.');
