INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Digitally marked goods run a much shorter clock: confirm or reject within one calendar day, or the invoice auto-confirms');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE code = 'UZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚠️ The one quantified sanction: Tax Code Article 223', NULL, NULL, 'Uzbekistan does not publish a schedule of fixed-sum fines for e-invoicing format, transmission or acceptance failures. It has one quantified sanction, and it is a blunt one: 20% of the concealed or understated tax base under Tax Code Article 223, applied where goods or services are sold without an electronic invoice being issued, or where it is issued late. Enforcement began on 1 April 2021, postponed from 1 March, and from that date taxpayers could back-issue invoices for prior periods only by accepting the 20% charge. One nuance worth knowing: Uzbek tax practitioners argue Article 223 is a concealment provision rather than a documentary-formality provision, and so should not bite where an invoice is lawfully issued after month-end within the Resolution 489 deadlines, since no tax distortion arises. The 20% figure is corroborated by two independent Uzbek sources but the verbatim article text could not be read directly in this research round — lex.uz serves the Tax Code as a single very large document that would not render the article body.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE code = 'UZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🚦 Risk scoring: no fine, but your buyer pays for it in cash flow', NULL, NULL, 'The system that went live on 1 January 2026 under Article 4 of Presidential Decree UP-153 carries no penalty whatsoever, which makes it easy to underestimate. Every invoice is scored in real time against criteria the Tax Committee has deliberately kept secret — reportedly 48 of them, withheld on international experts'' advice to prevent gaming — and flagged red or green, with the status visible to the buyer. Two consequences follow. A taxpayer''s flagged invoices must not exceed 10% of all invoices issued in a reporting period. And input VAT on a flagged invoice becomes creditable only once the tax has actually been paid into the budget by the seller or the buyer, which in practice pushes buyers either to wait for their supplier or to pay the VAT themselves. The commercial effect is that your risk status becomes your customers'' problem, and therefore your problem. Pilot figures cited at launch: 281 enterprises, 5.9 trillion sum of invoices and 706 billion sum of VAT credit at issue over July to September 2025.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE code = 'UZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '💳 Adjacent 2026 penalties, and what we could not confirm', NULL, NULL, 'Law ZRU-1108 introduced two adjacent fines from 1 January 2026 that are not e-invoicing sanctions but sit close enough to be worth knowing: UZS 5,000,000 for trading without the mandatory electronic payment systems and QR codes, and UZS 20,000,000 for using another taxpayer''s QR codes. Both are sourced to a professional-services alert rather than statute. Four items from this research round are flagged rather than presented as settled fact: the verbatim text of Tax Code Article 223 could not be read; Appendix 2 to Resolution 489, the operative procedural regulation, could not be retrieved in full; the JSON invoice format rests on consistent secondary sourcing with no primary technical specification located; and the two soliq.uz web properties are robots-blocked to automated checking, so their current availability was not independently verified.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE code = 'UZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm you are issuing electronic invoices at all', 'The obligation is universal for business entities and has been since 1 January 2020 — there is no threshold to fall under and no phase-in remaining. If any part of your Uzbek trade is still on paper, that is a live exposure under Article 223, not a pending deadline.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE code = 'UZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Get an ETsP digital signature and choose a channel', 'You need a digital signature certificate from the tax authority''s key centre, and either a state-platform account or an account with one of the 27 registered operators. Because the state roaming operator routes between operators, choosing a private one does not cut you off from any counterparty.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE code = 'UZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Put the buyer''s acceptance window into your own process', 'The buyer has ten days to certify or reject, and once that lapses the reject option disables and you can no longer cancel. Invoices for digitally marked goods run on a one-day clock with automatic confirmation. Chase acceptance rather than assuming silence is agreement.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'UZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Treat your risk status as a commercial issue, not just a tax one', 'Since January 2026 your invoices are scored and flagged, and a flagged invoice defers your customer''s input VAT recovery. Monitor your flagged ratio against the 10% ceiling, and expect buyers to start asking about it. The criteria are secret by design, so supplier and counterparty due diligence is the only real control.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'UZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Review the pre-filled VAT return within five working days', 'From January 2026 the tax authority generates your VAT and turnover-tax returns from your own invoice feed, and you have five working days to correct them. Reconcile continuously rather than at filing time — by the time the return appears, the underlying data is already the authority''s version of events.');
